  select id,'8957f6bb-9b23-4412-9c14-d25d3e2088de'::uuid,'Brand Builder (CI Manual) confirmed delivered, closing the last open chargeable Annexure B line. All three chargeable development areas are now complete - CI Manual, website and print promo. Ember360 monitoring continues.','Itemise the CI Manual in the August deck and reconcile the non-engaged status against three completed deliverables','Rinaldo Josie','2026-08-06'::timestamptz from iv;

select (select count(*) from beneficiaries where sponsor_id='4e401d68-a1e5-4b74-9a67-1ce9511569e4') bens,(select count(*) from interventions i join beneficiaries b on b.id=i.beneficiary_id where b.sponsor_id='4e401d68-a1e5-4b74-9a67-1ce9511569e4') ivs,(select count(*) from escalations e join beneficiaries b on b.id=e.beneficiary_id where b.sponsor_id='4e401d68-a1e5-4b74-9a67-1ce9511569e4') escs,(select count(*) from weekly_updates wu join interventions i on i.id=wu.intervention_id join beneficiaries b on b.id=i.beneficiary_id where b.sponsor_id='4e401d68-a1e5-4b74-9a67-1ce9511569e4') wus;
commit;

